<?php $labels=['draft'=>'Rascunho','sent'=>'Liberado','viewed'=>'Visualizado','signed'=>'Assinado','cancelled'=>'Cancelado'];$models=['fixed_plus_percentage'=>'Mensal + percentual','split_only'=>'Somente split']; ?>
<div class="page-header"><div><p class="eyebrow">Franquias</p><h1>Contratos</h1><p>Histórico completo, renovações, assinatura e modelo comercial da rede.</p></div><a class="button button-secondary" href="<?= $escape($basePath) ?>/admin/franchise-contract-templates"><i class="fa-solid fa-file-pen"></i> Modelos</a></div>
