<div class="table-card"><table><thead><tr><th>Contrato</th><th>Franquia</th><th>Tipo</th><th>Modelo</th><th>Situação</th><th>Assinatura</th><th>Ação</th></tr></thead><tbody><?php foreach($contracts as$item):?><tr><td><strong>#<?= (int)($item['contract_number']??1) ?> · <?= $escape($item['title']) ?></strong><small><?= $item['valid_from']?$escape(date('d/m/Y',strtotime((string)$item['valid_from']))):'Sem início' ?> — <?= $item['valid_until']?$escape(date('d/m/Y',strtotime((string)$item['valid_until']))):'indeterminada' ?></small></td><td><?= $escape($item['franchise_name']) ?><small><?= $escape($item['cnpj']) ?></small></td><td><?= ($item['contract_type']??'new')==='renewal'?'Renovação':'Novo' ?></td><td><?= $escape($models[$item['commercial_model']]??'Legado') ?></td><td><span class="status"><?= $escape($labels[$item['status']]??$item['status']) ?></span></td><td><?= $item['signed_at']?$escape(date('d/m/Y H:i',strtotime((string)$item['signed_at']))):'Pendente' ?></td><td><a class="button button-secondary button-small" href="<?= $escape($basePath) ?>/admin/franchise-contracts/<?= (int)$item['id'] ?>"><i class="fa-solid fa-eye"></i> Abrir</a></td></tr><?php endforeach;?><?php if($contracts===[]):?><tr><td colspan="7">Nenhum contrato gerado.</td></tr><?php endif;?></tbody></table></div>
